"""Docker Compose template generation for PostgreSQL+pgvector.

Generates a docker-compose.yml file in the .local directory
with PostgreSQL 16 and pgvector extension pre-installed.
"""

import os
from pathlib import Path

# Docker Compose template for PostgreSQL with pgvector
COMPOSE_TEMPLATE = """# Reverie PostgreSQL with pgvector
# Generated by Reverie Setup Wizard
# Data is stored in .local/postgres-data/

services:
  postgres:
    image: pgvector/pgvector:pg16
    container_name: reverie-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: ${POSTGRES_USER}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}
      POSTGRES_DB: ${POSTGRES_DB}
    volumes:
      - ./postgres-data:/var/lib/postgresql/data
    ports:
      - "${POSTGRES_PORT}:5432"
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${POSTGRES_USER} -d ${POSTGRES_DB}"]
      interval: 5s
      timeout: 5s
      retries: 5
"""


def get_local_dir(project_dir: Path | str | None = None) -> Path:
    """Get the .local directory path.

    Args:
        project_dir: Optional project root directory.
                    If None, uses the reverie package root (4 levels up).

    Returns:
        Path to the .local directory.
    """
    if project_dir:
        base = Path(project_dir)
    else:
        # Default to project root (src/reverie/docker -> project root)
        base = Path(__file__).parent.parent.parent.parent

    return base / ".local"


def generate_compose_file(
    project_dir: Path | str | None = None,
    postgres_user: str = "reverie",
    postgres_password: str = "reverie",
    postgres_db: str = "reverie",
    postgres_port: int = 5432,
) -> Path:
    """Generate docker-compose.yml file in .local directory.

    Args:
        project_dir: Optional project root directory.
        postgres_user: PostgreSQL username (default: reverie).
        postgres_password: PostgreSQL password (default: reverie).
        postgres_db: PostgreSQL database name (default: reverie).
        postgres_port: Host port to expose PostgreSQL (default: 5432).

    Returns:
        Path to the generated docker-compose.yml file.

    Raises:
        OSError: If directory creation or file write fails.
    """
    local_dir = get_local_dir(project_dir)

    # Create .local directory if it doesn't exist
    local_dir.mkdir(parents=True, exist_ok=True)

    # Generate compose content with substituted values
    compose_content = COMPOSE_TEMPLATE.replace(
        "${POSTGRES_USER}", postgres_user
    ).replace(
        "${POSTGRES_PASSWORD}", postgres_password
    ).replace(
        "${POSTGRES_DB}", postgres_db
    ).replace(
        "${POSTGRES_PORT}", str(postgres_port)
    )

    compose_path = local_dir / "docker-compose.yml"
    compose_path.write_text(compose_content)

    # Create .gitignore in .local to ignore data directory
    gitignore_path = local_dir / ".gitignore"
    if not gitignore_path.exists():
        gitignore_path.write_text("# Ignore PostgreSQL data\npostgres-data/\n")

    return compose_path


def get_compose_path(project_dir: Path | str | None = None) -> Path:
    """Get the path to docker-compose.yml.

    Args:
        project_dir: Optional project root directory.

    Returns:
        Path to docker-compose.yml (may not exist yet).
    """
    return get_local_dir(project_dir) / "docker-compose.yml"


def compose_exists(project_dir: Path | str | None = None) -> bool:
    """Check if docker-compose.yml exists.

    Args:
        project_dir: Optional project root directory.

    Returns:
        True if docker-compose.yml exists.
    """
    return get_compose_path(project_dir).exists()
